from full_a import cat, C

cat("prophets", "Prophets", "The people God sent to speak for Him.", "chariot", [
 dict(id="elijah", name="Elijah", role="The fiery prophet who never died", art="carmel",
  facts=["Faced 450 false prophets", "Fed by ravens", "Taken up in a whirlwind"], cards=[
  C("No rain", "Elijah told wicked King Ahab: no rain until I say so. Then he hid by a brook, where ravens brought him bread and meat.",
    "Ahab and Queen Jezebel had made Baal — the supposed storm god — Israel’s official religion. A drought was a direct challenge to Baal. It lasted three and a half years.", ("1 Kings",17)),
  C("The widow’s flour", "Elijah stayed with a starving widow in Zarephath. Her flour and oil never ran out — and he raised her son from the dead.",
    "She had only enough for one last meal. Elijah asked her to make him a small loaf first. She did, and the jar never ran empty until the rain came.", ("1 Kings",17)),
  C("Fire on Mount Carmel", "Elijah challenged 450 prophets of Baal. Their god never answered. Elijah drenched his altar, prayed once, and fire fell from heaven.",
    "He mocked them: “Shout louder! Maybe he’s sleeping or traveling.” They cut themselves and raved all day. Elijah had twelve jars of water poured on his sacrifice. His prayer was simple: “Let it be known today that You are God in Israel.” Fire consumed everything, even the water. The people shouted, “The Lord — He is God!” Then Elijah prayed seven times, and a small cloud became a downpour.", ("1 Kings",18)),
  C("Burned out", "Jezebel vowed to kill him. Elijah ran into the desert and asked to die. An angel fed him and let him sleep.",
    "He traveled 40 days to Mount Horeb. There came a wind, an earthquake and a fire — but God wasn’t in them. Then a gentle whisper: “What are you doing here, Elijah?” God told him he wasn’t alone — 7,000 had not bowed to Baal — and gave him a successor, Elisha.", ("1 Kings",19)),
  C("Naboth’s vineyard", "When Jezebel had an innocent man killed so Ahab could take his vineyard, Elijah confronted the king.",
    "Ahab said, “So you have found me, my enemy!” Elijah foretold dogs licking Ahab’s blood and eating Jezebel — both later happened.", ("1 Kings",21)),
  C("Chariot of fire", "Elijah didn’t die. A chariot of fire appeared, and he was taken up to heaven in a whirlwind as Elisha watched.",
    "The prophet Malachi promised Elijah would come again before the day of the Lord. Jesus said John the Baptist came in Elijah’s spirit, and Elijah himself appeared at the Transfiguration.", ("2 Kings",2)),
 ]),
 dict(id="elisha", name="Elisha", role="Elijah’s apprentice, with a double portion", art=None,
  facts=["Left his plow to follow Elijah", "Asked for a “double portion”", "Many miracles"], cards=[
  C("Burning the plow", "Elijah threw his cloak over Elisha in the field. Elisha slaughtered his oxen, burned the plow, threw a feast, and followed.",
    "There was no going back.", ("1 Kings",19)),
  C("A double portion", "Elisha asked for a double share of Elijah’s spirit. After Elijah was taken up, Elisha struck the Jordan with his cloak and it parted.",
    "The Bible records about twice as many miracles for Elisha as for Elijah.", ("2 Kings",2)),
  C("Oil and a boy raised", "A widow’s single jar of oil filled every jar she could borrow. A couple’s son died, and Elisha raised him to life.",
    "The Shunammite woman had built a little room for Elisha. He promised her a son; years later the boy died and Elisha brought him back.", ("2 Kings",4)),
  C("Naaman’s healing", "A Syrian army commander with leprosy was told to wash in the Jordan seven times. Annoyed, he did — and his skin became like a child’s.",
    "A captive Israelite servant girl told Naaman’s wife about the prophet. Naaman declared, “Now I know there is no God in all the world except in Israel.”", ("2 Kings",5)),
  C("Horses and chariots of fire", "Surrounded by an enemy army, Elisha’s servant panicked. Elisha prayed, and his eyes opened to see hills full of fiery chariots.",
    "“Don’t be afraid. Those who are with us are more than those who are with them.”", ("2 Kings",6)),
 ]),
 dict(id="isaiah", name="Isaiah", role="The prophet who saw Jesus coming 700 years early", art="isaiah",
  facts=["Saw God’s throne", "“Here I am, send me”", "Most quoted prophet in the New Testament"], cards=[
  C("Holy, holy, holy", "Isaiah saw the Lord on His throne, with seraphim calling, “Holy, holy, holy.” He cried, “Woe is me! I am a man of unclean lips.”",
    "A seraph touched his lips with a coal from the altar: “Your guilt is taken away.”", ("Isaiah",6)),
  C("Send me", "God asked, “Whom shall I send?” Isaiah said, “Here am I. Send me!” He served about 60 years under four kings.",
    "God warned him people wouldn’t listen. He counseled kings Ahaz and Hezekiah.", ("Isaiah",6)),
  C("A child is born", "Isaiah foretold a virgin’s son named Immanuel and a child called “Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace.”",
    "Matthew quotes Isaiah 7 about Jesus’ birth.", ("Isaiah",9)),
  C("The suffering servant", "Isaiah described a servant “pierced for our transgressions” and “led like a lamb to the slaughter” — fulfilled in Jesus.",
    "“We all, like sheep, have gone astray… and the Lord has laid on Him the iniquity of us all.” A scroll of Isaiah found among the Dead Sea Scrolls dates to about 100 years before Jesus.", ("Isaiah",53)),
 ]),
 dict(id="jeremiah", name="Jeremiah", role="The weeping prophet", art="jeremiah",
  facts=["Called as a teen", "Warned Jerusalem for 40 years", "Thrown into a muddy well"], cards=[
  C("“Before you were born”", "God called young Jeremiah: “Before I formed you in the womb I knew you.” Jeremiah said he was too young.",
    "God touched his mouth: “I have put My words in your mouth.”", ("Jeremiah",1)),
  C("An unpopular message", "For 40 years Jeremiah warned Judah that Babylon would conquer them. He was beaten, put in stocks and called a traitor.",
    "God told him not to marry, as a sign of the coming disaster. King Jehoiakim cut up his scroll and burned it piece by piece; Jeremiah dictated it again.", ("Jeremiah",36)),
  C("In the mud", "Officials lowered Jeremiah into a muddy cistern to die. A foreign servant, Ebed-Melech, pulled him out with ropes and rags.",
    "He sank into the mud with no water.", ("Jeremiah",38)),
  C("A future and a hope", "Even as Jerusalem fell, Jeremiah promised, “I know the plans I have for you — plans to give you hope and a future.”",
    "He also promised a new covenant written on hearts. Lamentations, traditionally linked with him, mourns the fallen city and says, “His mercies are new every morning.”", ("Jeremiah",29)),
 ]),
 dict(id="daniel", name="Daniel", role="The teenager who stayed faithful in Babylon", art="lions-den",
  facts=["Taken captive as a teen", "Interpreted dreams", "Survived the lions’ den"], cards=[
  C("Taken to Babylon", "Babylon conquered Jerusalem and took its best young men, including Daniel, to train for the king’s service.",
    "Daniel refused the king’s rich food and asked for vegetables and water for ten days. He and his friends ended up healthier than everyone else, and wiser.", ("Daniel",1)),
  C("The king’s dream", "Nebuchadnezzar demanded someone tell him his dream and its meaning — or all wise men would die. God revealed it to Daniel.",
    "The dream was a statue of gold, silver, bronze and iron, smashed by a rock that became a mountain — kingdoms rising and falling, and God’s kingdom lasting forever.", ("Daniel",2)),
  C("Writing on the wall", "At King Belshazzar’s feast, a hand wrote on the wall. Daniel read it: your kingdom is over. That night the king was killed.",
    "Babylon fell to the Medes and Persians in 539 BC.", ("Daniel",5)),
  C("The lions’ den", "Under the Persians, rivals got a law banning prayer to anyone but the king. Daniel kept praying, was thrown to the lions, and survived.",
    "Daniel was in his 80s. King Darius couldn’t sleep, ran to the den at dawn, and found him unharmed: “My God sent His angel and shut the mouths of the lions.”", ("Daniel",6)),
  C("Visions of the future", "Daniel saw visions of beasts, empires, and “one like a son of man” coming with the clouds of heaven.",
    "Jesus’ favorite title for Himself, “Son of Man,” comes from this vision in Daniel 7.", ("Daniel",7)),
 ]),
 dict(id="shadrach", name="Shadrach, Meshach & Abednego", role="Three friends who wouldn’t bow", art="furnace",
  facts=["Daniel’s friends", "Refused to worship a statue", "A fourth man in the fire"], cards=[
  C("Daniel’s friends", "Hananiah, Mishael and Azariah were renamed Shadrach, Meshach and Abednego in Babylon.",
    "They trained alongside Daniel and became officials in Babylon.", ("Daniel",1)),
  C("“Even if He does not”", "Nebuchadnezzar ordered all to bow to a 90-foot golden statue. They refused: “Our God can save us — but even if He doesn’t, we won’t bow.”",
    "The furnace was heated seven times hotter; the soldiers who threw them in died from the heat.", ("Daniel",3)),
  C("The fourth man", "The king saw four men walking in the fire, unbound, and the fourth looked like a son of the gods.",
    "They came out without even the smell of smoke. The king praised their God and promoted them.", ("Daniel",3)),
 ]),
 dict(id="jonah", name="Jonah", role="The prophet who ran from God", art="jonah-whale",
  facts=["Ran the other way", "Swallowed by a great fish", "Upset when God forgave"], cards=[
  C("Running away", "God sent Jonah to warn Nineveh, capital of brutal Assyria. Jonah boarded a ship headed the opposite way, to Tarshish.",
    "Assyria was Israel’s cruelest enemy. Jonah didn’t want them to have a chance to repent.", ("Jonah",1)),
  C("Overboard", "A violent storm hit. Jonah admitted it was his fault and told the sailors to throw him overboard. The sea went calm.",
    "The pagan sailors prayed to the Lord and offered sacrifices.", ("Jonah",1)),
  C("The great fish", "God sent a huge fish to swallow Jonah. After three days and nights of praying, it spit him onto dry land.",
    "Jesus pointed to this as a sign: “As Jonah was three days and three nights in the belly of a huge fish, so the Son of Man will be three days and three nights in the heart of the earth.”", ("Jonah",2)),
  C("Nineveh repents", "Jonah preached: “Forty days and Nineveh will be overthrown.” The whole city, even the king, repented. God spared them.",
    "The king wore sackcloth and sat in the dust, and ordered even the animals to fast.", ("Jonah",3)),
  C("Angry at mercy", "Jonah was furious. God grew a plant to shade him, then let it die. “You care about a plant. Shouldn’t I care about this great city?”",
    "Jonah had said, “I knew You are a gracious and compassionate God… That’s why I ran.” The book ends with God’s question unanswered.", ("Jonah",4)),
 ]),
 dict(id="job", name="Job", role="The good man who lost everything", art="job",
  facts=["Lost his family and wealth", "Asked God “why?”", "Restored double"], cards=[
  C("Blameless", "Job was rich, honest and devoted to God. Satan claimed Job only served God because God protected him.",
    "God allowed Satan to test Job, but not take his life.", ("Job",1)),
  C("Everything gone", "In one day Job lost his livestock, servants and all ten children. He worshiped: “The Lord gave and the Lord has taken away.”",
    "Then he was struck with painful sores from head to foot. His wife said, “Curse God and die!” He replied, “Shall we accept good from God, and not trouble?”", ("Job",2)),
  C("Bad comfort", "Three friends sat with him in silence for seven days — then insisted he must have sinned. Job knew he hadn’t.",
    "Job poured out his anguish honestly, yet also said, “I know that my redeemer lives.”", ("Job",19)),
  C("God answers", "God spoke from a storm, not with explanations but questions: “Where were you when I laid the foundations of the earth?”",
    "Job was humbled: “I spoke of things I did not understand.” God rebuked the friends, restored Job’s fortune double, and gave him ten more children.", ("Job",38)),
 ]),
])

cat("villains", "Villains & Rivals", "The people who opposed God — and how it turned out.", "darkness", [
 dict(id="pharaoh", name="Pharaoh of the Exodus", role="The king who wouldn’t let God’s people go", art="passover",
  facts=["King of Egypt", "Ten plagues", "Chased Israel into the sea"], cards=[
  C("“Who is the Lord?”", "When Moses said, “Let My people go,” Pharaoh scoffed and made the slaves gather their own straw for bricks.",
    "The Bible never names him.", ("Exodus",5)),
  C("A hardened heart", "Through ten plagues Pharaoh promised to release Israel, then changed his mind every time.",
    "Some plagues his magicians copied; by the gnats they admitted, “This is the finger of God.”", ("Exodus",8)),
  C("The final plague", "After his own firstborn son died, Pharaoh finally told Israel to go.", "", ("Exodus",12)),
  C("How it ended", "He changed his mind once more, chased Israel with 600 chariots, and his army drowned in the Red Sea.", "", ("Exodus",14)),
 ]),
 dict(id="goliath", name="Goliath", role="The giant who mocked God", art="goliath",
  facts=["Over 9 feet tall", "Philistine champion", "Beaten by a boy with a sling"], cards=[
  C("The champion", "Goliath of Gath stood over nine feet tall in bronze armor weighing about 125 pounds. His spearhead alone weighed 15 pounds.",
    "Ancient manuscripts differ — some say about 6’9” — still a giant in that era.", ("1 Samuel",17)),
  C("40 days of taunting", "Morning and evening for 40 days he challenged Israel to send one man to fight him. No one dared.", "", ("1 Samuel",17)),
  C("How it ended", "A shepherd boy named David killed him with one stone from a sling.", "", ("1 Samuel",17)),
 ]),
 dict(id="jezebel", name="Jezebel", role="The queen who led Israel to worship Baal", art=None,
  facts=["Wife of King Ahab", "Killed God’s prophets", "Threatened Elijah"], cards=[
  C("A foreign queen", "Jezebel, a princess of Sidon, married King Ahab and pushed Baal worship on Israel, killing the Lord’s prophets.",
    "She supported 450 prophets of Baal and 400 of Asherah at her table.", ("1 Kings",16)),
  C("Naboth’s vineyard", "When Naboth wouldn’t sell his vineyard, Jezebel arranged false witnesses and had him stoned.", "", ("1 Kings",21)),
  C("How it ended", "When Jehu took the throne, Jezebel painted her eyes and taunted him from a window. Her servants threw her down.", "Dogs ate her body, just as Elijah had foretold.", ("2 Kings",9)),
 ]),
 dict(id="haman", name="Haman", role="The official who plotted to wipe out the Jews", art="esther",
  facts=["Top official in Persia", "Hated Mordecai", "Built his own gallows"], cards=[
  C("Wounded pride", "Haman was second only to the king. When Mordecai refused to bow, Haman plotted to kill every Jew in the empire.", "", ("Esther",3)),
  C("Humiliated", "The king asked Haman how to honor a hero. Thinking it was himself, he suggested a parade — then had to lead it for Mordecai.", "", ("Esther",6)),
  C("How it ended", "Queen Esther exposed him. He was hanged on the 75-foot gallows he built for Mordecai.", "", ("Esther",7)),
 ]),
 dict(id="herod", name="King Herod the Great", role="The king who tried to kill baby Jesus", art="nativity",
  facts=["King of Judea under Rome", "Rebuilt the Temple", "Paranoid and cruel"], cards=[
  C("Builder and tyrant", "Herod ruled Judea for Rome from 37 to 4 BC. He rebuilt the Temple on a grand scale — and executed his own wife and three sons.",
    "The historian Josephus describes his cruelty. The Western Wall in Jerusalem is part of his Temple platform.", ("Matthew",2)),
  C("The wise men", "When Magi asked about a newborn King of the Jews, Herod pretended he wanted to worship Him.", "", ("Matthew",2)),
  C("How it ended", "Herod ordered all boys two and under in Bethlehem killed. Jesus’ family escaped to Egypt. Herod died soon after.", "", ("Matthew",2)),
 ]),
 dict(id="pilate", name="Pontius Pilate", role="The governor who sent Jesus to the cross", art="ecce-homo",
  facts=["Roman governor of Judea", "Found no fault in Jesus", "Washed his hands"], cards=[
  C("Roman governor", "Pilate governed Judea from about AD 26 to 36. A stone inscribed with his name was found at Caesarea in 1961.",
    "Josephus and Philo describe him as harsh and provocative toward the Jews.", ("Luke",23)),
  C("“What is truth?”", "Pilate questioned Jesus: “Are You the king of the Jews?” Jesus said His kingdom is not of this world. Pilate asked, “What is truth?”", "", ("John",18)),
  C("Washing his hands", "Pilate found no guilt in Jesus and his wife warned him, but the crowd shouted, “Crucify Him!” He washed his hands and handed Jesus over.",
    "He released Barabbas, a murderer, instead. He had the sign “King of the Jews” placed on the cross and refused to change it.", ("Matthew",27)),
 ]),
])
